-- Official-source verified expansion: voice infrastructure and AI analytics.

insert into public.tools (
 name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,
 korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,
 is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at
)
select * from (values
('Deepgram','실시간 음성 인식·음성 합성·대화형 음성 에이전트를 제공하는 개발자 API #음성인식 #음성합성 #VoiceAI #API','Deepgram은 실시간·배치 음성 인식, 저지연 음성 합성, 오디오 분석과 LLM 오케스트레이션을 하나의 API 플랫폼에서 제공하며 클라우드와 기업용 자체 배포를 지원합니다.','https://deepgram.com/','https://deepgram.com/favicon.ico','Freemium','$0','신규 계정 $200 크레딧 · 사용량 기반 과금',array['신규 계정에 만료 기한 없는 $200 무료 크레딧을 제공합니다.','Nova-3 영어 배치 음성 인식은 분당 $0.0043부터, 실시간은 분당 $0.0077부터입니다.','Aura-1 음성 합성은 1,000자당 $0.015부터, 표준 Voice Agent API는 분당 $0.075입니다.'],'USD','https://deepgram.com/pricing',now(),'Partial Support',true,true,false,false,false,'official_sources','공식 제품·가격·개발자 문서를 확인했습니다. 한국어 정확도, API 응답과 실제 과금은 직접 테스트하지 않았습니다.',false,true,'https://developers.deepgram.com/','Native','specialized',array['실시간·배치 음성 인식','저지연 음성 합성','Voice Agent API'],array['화자 분리·감정 분석','다국어 처리','자체 호스팅'],array['STT·TTS·에이전트 통합','만료 없는 시작 크레딧','실시간 스트리밍 API'],array['음성 에이전트를 개발하는 팀','통화·미디어 음성을 분석하는 서비스'],array['모델과 데이터 제공 동의 여부에 따라 단가가 달라질 수 있습니다.','멀티채널 음성은 채널별 길이를 합산해 과금합니다.','한국어 품질과 지연시간은 실제 오디오로 검증해야 합니다.'],array['https://deepgram.com/','https://deepgram.com/pricing','https://developers.deepgram.com/reference/text-to-speech/speak-request'],now(),now()),
('Speechmatics','55개 이상 언어의 실시간·파일 음성 인식과 음성 합성을 제공하는 API #음성인식 #자막 #VoiceAI #API','Speechmatics는 실시간 및 배치 음성을 텍스트로 변환하고 화자 분리·언어 식별·번역·요약을 적용하며, 기업에는 자체 환경 배포와 맞춤 모델도 제공하는 음성 플랫폼입니다.','https://www.speechmatics.com/','https://www.speechmatics.com/favicon.ico','Freemium','$0','시작 크레딧 $100 · STT 시간당 $0.129부터',array['카드 없이 $100 시작 크레딧을 제공합니다.','Pro 배치 Melia 1은 시간당 $0.129, 실시간 Standard는 시간당 $0.24부터입니다.','음성 합성은 1,000자당 $0.011이며 번역·요약 등은 별도 사용량으로 과금됩니다.'],'USD','https://www.speechmatics.com/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 가격·언어·개발자 문서에서 한국어 포함과 API 기능을 확인했습니다. 실제 한국어 전사와 API는 직접 테스트하지 않았습니다.',false,true,'https://docs.speechmatics.com/','Native','specialized',array['실시간·배치 음성 인식','화자 분리·언어 식별','음성 합성'],array['번역·요약·감정 분석','사용자 사전','온프레미스 배포'],array['공식 한국어 지원','초 단위 사용량 과금','기업용 다양한 배포 방식'],array['다국어 회의·미디어 전사 서비스','보안 환경에 음성 AI를 배포하는 기업'],array['무료 크레딧 소진 후 결제수단을 등록해야 서비스가 계속됩니다.','학습 데이터 제공 할인 선택 시 음성과 전사문 사용을 허용하게 됩니다.','TTS는 현재 공식 페이지상 영어 중심입니다.'],array['https://www.speechmatics.com/pricing','https://docs.speechmatics.com/'],now(),now()),
('Gladia','100개 이상 언어의 실시간·비동기 전사와 오디오 분석을 제공하는 음성 API #음성인식 #다국어 #자막 #API','Gladia는 녹음 파일과 실시간 스트림을 전사하고 자동 언어 감지·전환, 화자 분리와 타임스탬프를 제공하는 개발자용 다국어 음성 인식 API입니다.','https://www.gladia.io/','https://www.gladia.io/favicon.ico','Freemium','$0','무료 €50 크레딧 · 비동기 시간당 $0.61부터',array['Starter에 €50 무료 크레딧이 포함됩니다.','Starter 비동기 전사는 시간당 $0.61, 실시간 전사는 시간당 $0.75입니다.','Growth는 약정에 따라 비동기 $0.20, 실시간 $0.25까지 낮아질 수 있습니다.'],'USD','https://www.gladia.io/pricing',now(),'Partial Support',true,true,false,false,false,'official_sources','공식 가격·API 문서에서 100개 이상 언어와 기능을 확인했습니다. 한국어 지원 목록·정확도와 API는 직접 테스트하지 않았습니다.',false,true,'https://docs.gladia.io/api-reference','Native','specialized',array['실시간·비동기 음성 전사','자동 언어 감지·전환','화자 분리'],array['단어별 타임스탬프','오디오 인텔리전스','웹훅·동시 처리'],array['100개 이상 언어 처리','무료 API 크레딧','실시간과 파일 전사 통합'],array['다국어 회의 보조 도구 개발팀','콘텐츠·콜센터 음성을 처리하는 서비스'],array['Growth 최저 단가는 선결제 약정과 사용량 조건이 필요합니다.','언어별 정확도는 음질과 도메인에 따라 달라집니다.','한국어는 별도 샘플 검증 전까지 부분 지원으로 표시합니다.'],array['https://www.gladia.io/pricing','https://docs.gladia.io/api-reference'],now(),now()),
('Cartesia','저지연 음성 합성·음성 인식·전화 음성 에이전트를 구축하는 API #음성합성 #음성인식 #VoiceAgent #API','Cartesia는 스트리밍 음성 합성 Sonic, 음성 인식 Ink와 전화 기반 Line 에이전트를 제공하며 즉시·전문 음성 복제와 동시 통화 기능을 지원하는 음성 AI 플랫폼입니다.','https://www.cartesia.ai/','https://www.cartesia.ai/favicon.ico','Freemium','$0','월 20,000 크레딧 무료 · Pro 월 $5',array['Free는 월 20,000 크레딧과 TTS 약 27분, STT 약 1시간 51분을 제공합니다.','Pro는 월 $5에 100,000 크레딧과 상업적 사용·즉시 음성 복제를 제공합니다.','Voice Agent 통화는 분당 $0.06, Cartesia 전화번호 사용 시 통신료 분당 $0.014가 추가됩니다.'],'USD','https://www.cartesia.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 가격·개발자 문서를 확인했습니다. 한국어 음성, 복제 권한 확인과 API는 직접 테스트하지 않았습니다.',false,true,'https://docs.cartesia.ai/get-started/overview','Native','specialized',array['스트리밍 음성 합성','실시간 음성 인식','전화 음성 에이전트'],array['즉시·전문 음성 복제','Voice Changer','동시 통화'],array['무료 월간 크레딧','낮은 Pro 시작 가격','STT·TTS·에이전트 단일 플랫폼'],array['실시간 음성 앱 개발자','전화 상담 에이전트를 구축하는 팀'],array['무료 플랜은 상업적 사용 라이선스가 포함되지 않습니다.','에이전트 비용에 전화·외부 모델 비용이 추가될 수 있습니다.','음성 복제 시 화자 동의와 사용 권한을 확인해야 합니다.'],array['https://www.cartesia.ai/pricing','https://docs.cartesia.ai/get-started/overview'],now(),now()),
('ThoughtSpot Spotter','업무 데이터를 자연어로 분석하고 근거를 추적해 실행까지 연결하는 AI 분석가 #데이터분석 #BI #AI에이전트 #대시보드','ThoughtSpot Spotter는 관리된 시맨틱 계층을 바탕으로 자연어 질문을 분석하고 검증 가능한 답과 시각화를 만들며 Jira·Salesforce·Slack 등의 후속 작업과 제품 내 임베딩을 지원합니다.','https://www.thoughtspot.com/product/agents/spotter','https://www.thoughtspot.com/favicon.ico','Paid','$25','사용자당 월 $25부터 · AI 포함 플랜 월 $50부터',array['Essentials는 연간 결제 기준 사용자당 월 $25부터입니다.','자연어 분석과 Spotter 월 25회 질문을 포함하는 Pro는 사용자당 월 $50부터입니다.','사용량 기반 플랜은 크레딧당 $0.10부터이며 자체 LLM 사용 시 해당 공급자 비용이 추가됩니다.'],'USD','https://www.thoughtspot.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 Spotter 제품·가격 페이지를 확인했습니다. 데이터 연결, 답변 정확도와 API·SDK는 직접 테스트하지 않았습니다.',false,true,'https://developers.thoughtspot.com/','Augmented','specialized',array['자연어 데이터 분석','자동 인사이트·시각화','분석 에이전트'],array['시맨틱 계층·감사 가능 쿼리','업무 도구 작업 실행','웹 API·SDK 임베딩'],array['비개발자의 자연어 분석','분석 근거 추적','제품 안에 AI 분석 기능 삽입'],array['관리된 업무 데이터를 탐색하는 팀','고객 제품에 분석 기능을 넣는 개발사'],array['신뢰도는 데이터 모델과 시맨틱 계층 품질에 좌우됩니다.','Pro 기본 제공 Spotter 질문 수에 제한이 있습니다.','자체 LLM을 연결하면 별도 모델 비용이 생길 수 있습니다.'],array['https://www.thoughtspot.com/product/agents/spotter','https://www.thoughtspot.com/pricing','https://www.thoughtspot.com/blog/introducing-spotter-ai-analyst'],now(),now()),
('Obviously AI','코드 없이 표 데이터로 예측 모델·AI 에이전트와 자동화를 만드는 플랫폼 #NoCode #예측분석 #AutoML #데이터분석','Obviously AI는 CSV와 업무 데이터를 이용해 분류·회귀·시계열 예측 모델을 만들고 웹 앱·REST API로 배포하며 에이전트·자동화·모니터링까지 연결하는 노코드 AI 플랫폼입니다.','https://obviously.ai/','https://obviously.ai/favicon.ico','Paid',null,'플랜별 맞춤 가격 · 상담 필요',array['Startup·SMB·Enterprise 구성이 공개되어 있으나 현재 공식 페이지에 정액 금액은 표시되지 않습니다.','Software Only 또는 전담 데이터 과학자가 포함된 구성을 선택할 수 있습니다.','처리 데이터·예측 횟수·사용 사례와 기업 보안 요구에 따라 견적이 달라집니다.'],'USD','https://obviously.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 페이지에서 기능과 REST API 제공을 확인했습니다. 가격, 모델 정확도와 배포 API는 직접 테스트하지 않았습니다.',false,true,'https://obviously.ai/pricing','Native','specialized',array['노코드 예측 모델','AI 에이전트·워크플로','원클릭 모델 배포'],array['REST API','모델 모니터링','전담 데이터 과학자 옵션'],array['코딩 없이 분류·회귀·시계열 예측','웹 앱과 API 배포','데이터 전문가 지원 선택'],array['데이터 과학 인력이 부족한 업무팀','빠르게 예측 모델을 시험하는 중소기업'],array['공개 정액 가격이 없어 사전 비용 비교가 어렵습니다.','결과 품질은 입력 데이터 정제와 문제 설정에 좌우됩니다.','고위험 의사결정에는 편향·정확도 검증과 사람 검토가 필요합니다.'],array['https://obviously.ai/','https://obviously.ai/pricing'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://deepgram.com/','video-audio'),('https://deepgram.com/','development'),
('https://www.speechmatics.com/','video-audio'),('https://www.speechmatics.com/','development'),
('https://www.gladia.io/','video-audio'),('https://www.gladia.io/','development'),
('https://www.cartesia.ai/','video-audio'),('https://www.cartesia.ai/','development'),
('https://www.thoughtspot.com/product/agents/spotter','search-data'),('https://www.thoughtspot.com/product/agents/spotter','business-marketing'),
('https://obviously.ai/','search-data'),('https://obviously.ai/','business-marketing')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
